export type NetworkMode = "none" | "public_internet";

/** A freshly minted key. The value never appears in a later read. */
export interface NewApiKey {
  readonly createdAt: string;
  readonly id: Id<"api_key">;
  readonly name: string;
  readonly scopes: ReadonlyArray<"account:read" | "account:write" | "organizations:read" | "organizations:write" | "memberships:read" | "memberships:write" | "memberships:accept" | "workspaces:read" | "workspaces:write" | "workspaces:delete" | "api_keys:read" | "api_keys:write" | "billing:read" | "billing:write" | "operations:read" | "operations:write" | "workspace:read" | "sessions:read" | "sessions:write" | "sessions:delete" | "files:live" | "resources:read" | "resources:write" | "provider_credentials:read" | "provider_credentials:write">;
  readonly value: string;
  readonly workspaceId: Id<"workspace">;
}

/** A durable operation record. */
export interface Operation {
  readonly cancelable: boolean;
  readonly committedAt?: string;
  readonly createdAt: string;
  readonly error?: OperationFailure;
  readonly id: Id<"operation">;
  readonly kind: OperationKind;
  readonly progress?: OperationProgress;
  readonly result?: OperationResult;
  readonly sessionId?: Id<"session">;
  readonly startedAt?: string;
  readonly status: OperationStatus;
  readonly terminalAt?: string;
  readonly updatedAt: string;
  readonly workspaceId: Id<"workspace">;
}

/** A durable operation failure. It carries no synthetic request identity. */
export interface OperationFailure {
  readonly code: "unauthenticated" | "forbidden" | "insufficient_scope" | "token_invalid" | "token_revoked" | "token_expired" | "malformed_token" | "authorization_pending" | "slow_down" | "not_found" | "gone" | "idempotency_conflict" | "idempotency_in_flight" | "api_key_secret_unavailable" | "operation_idempotency_conflict" | "invalid_request" | "invalid_scope" | "invalid_cursor" | "invalid_file_selection" | "invalid_range" | "unsupported_media_type" | "payload_too_large" | "limit_exceeded" | "session_not_idle" | "session_terminated" | "workspace_activation_required" | "workspace_not_live" | "session_deleting" | "session_deleted" | "deletion_in_progress" | "resource_conflict" | "last_owner_required" | "operation_not_cancelable" | "approval_not_found" | "approval_already_resolved" | "approval_binding_changed" | "file_not_found" | "content_missing" | "download_grant_expired" | "invalid_query" | "invalid_network_policy" | "unsupported_package_ecosystem" | "package_resolution_failed" | "package_artifact_unavailable" | "package_integrity_mismatch" | "unknown_provider" | "unknown_model" | "provider_credential_not_found" | "provider_credential_revoked" | "invalid_auto_topup_policy" | "payment_method_required" | "authentication_unavailable" | "account_paused" | "account_state_unavailable" | "precondition_failed" | "wrong_workspace_region" | "usage_unavailable" | "rate_limited" | "upstream_error" | "workspace_provision_pending" | "commit_outcome_unknown" | "not_implemented" | "internal_error";
  readonly detail?: JsonValue;
  readonly retryable: boolean;
}

/** Every durable operation the platform admits. */
export type OperationKind = "session_cancel" | "session_suspend" | "session_resume" | "session_terminate" | "session_delete" | "workspace_delete";

/** One page of durable operations. */
export interface OperationPage {
  readonly items: ReadonlyArray<Operation>;
  readonly nextCursor?: string;
}

/** Coarse progress; never a completion promise. */
export interface OperationProgress {
  readonly completed?: string;
  readonly phase: string;
  readonly total?: string;
}

/** The typed successful result of a durable operation. */
export type OperationResult = (SessionCancelResult & { readonly kind: "session_cancel" }) | (SessionSuspendResult & { readonly kind: "session_suspend" }) | (SessionResumeResult & { readonly kind: "session_resume" }) | (SessionTerminateResult & { readonly kind: "session_terminate" }) | (SessionTombstone & { readonly kind: "session_delete" }) | (WorkspaceTombstone & { readonly kind: "workspace_delete" });

/** Where a durable operation is in its lifecycle. */
export type OperationStatus = "queued" | "running" | "succeeded" | "failed" | "cancelled";

/** Where a workspace operational state comes from. */
export type OperationalStateSource = "account";

/** The billing and ownership boundary. */
export interface Organization {
  readonly callerRole: OrganizationRole;
  readonly createdAt: string;
  readonly id: Id<"organization">;
  readonly name: string;
  readonly slug: string;
}

/** One organization's operational state in a multi-organization dashboard snapshot. */
export interface OrganizationAccount {
  readonly organizationId: Id<"organization">;
  readonly state: AccountOperationalState;
}

/** Create an organization. */
export interface OrganizationCreateRequest {
  readonly name: string;
}

/** One page of organizations. */
export interface OrganizationPage {
  readonly items: ReadonlyArray<Organization>;
  readonly nextCursor?: string;
}

/** The caller role inside one organization. */
export type OrganizationRole = "owner" | "admin" | "member";

/** The package ecosystems a session may pre-install from. */
export type PackageEcosystem = "apt" | "pip" | "npm";

/** One exactly-pinned package to pre-install. */
export interface PackageRequest {
  readonly ecosystem: PackageEcosystem;
  readonly name: string;
  readonly version: string;
}

/** Create a hosted billing portal session. */
export interface PortalSessionRequest {
  readonly returnUrl?: string;
}

/** A BYOK provider-credential binding. The key material never appears here. */
export interface ProviderCredential {
  readonly createdAt: string;
  readonly fingerprint: string;
  readonly id: Id<"provider_credential">;
  readonly name: string;
  readonly provider: ProviderId;
  readonly revision: number;
  readonly revokedAt?: string;
  readonly state: ProviderCredentialState;
  readonly updatedAt: string;
}

/** One page of provider-credential bindings. */
export interface ProviderCredentialPage {
  readonly items: ReadonlyArray<ProviderCredential>;
  readonly nextCursor?: string;
}

/** Register a BYOK provider credential. This request carries plaintext. */
export interface ProviderCredentialRegisterRequest {
  readonly apiKey: string;
  readonly name: string;
  readonly provider: ProviderId;
}

/** Whether a BYOK binding may still be selected. */
export type ProviderCredentialState = "ready" | "revoked";

/** The eight customer-owned BYOK authorities. Gateway authorities use fixed endpoints; arbitrary base URLs are not accepted. */
export type ProviderId = "openai" | "anthropic" | "deepseek" | "zai" | "moonshotai" | "google" | "openrouter" | "vercel_ai_gateway";

/** A registered file entry, complete. */
export interface RegisteredFile {
  readonly createdAt: string;
  readonly name: string;
  readonly revision: number;
  readonly sha256: string;
  readonly sizeBytes: string;
  readonly state: RegisteredState;
  readonly updatedAt: string;
  readonly value: RegisteredFileRead;
}

/** The two permitted registered-file modes. */
export type RegisteredFileMode = "0644" | "0755";

/** One page of registered files. */
export interface RegisteredFilePage {
  readonly items: ReadonlyArray<RegisteredFileRow>;
  readonly nextCursor?: string;
}

/** What a registered file is, as published. The payload bytes are referenced, never inlined; fetch them with a download grant. */
export interface RegisteredFileRead {
  readonly content: ContentRef;
  readonly mediaType: string;
  readonly mode: RegisteredFileMode;
  readonly mountPath: string;
}

/** One registered file as a collection row. A listing carries no value document; read the entry itself to get one. */
export interface RegisteredFileRow {
  readonly createdAt: string;
  readonly name: string;
  readonly revision: number;
  readonly sha256: string;
  readonly sizeBytes: string;
  readonly state: RegisteredState;
  readonly updatedAt: string;
}

/** A registered file. */
export interface RegisteredFileValue {
  readonly content: BlobInput;
  readonly mediaType: string;
  readonly mode: RegisteredFileMode;
  readonly mountPath: string;
}

/** The only state a registered entry has; there is no version history. */
export type RegisteredState = "current";

/** Mint a download grant for a registered file. */
export interface RegistryDownloadRequest {
  readonly range?: ByteRange;
}

/** The complete provider-derived capacity of the selected shape. */
export interface ResolvedCompute {
  readonly baseline: ComputeShape;
  readonly endpointBandwidthMBps: number;
  readonly maxConcurrentConnections: number;
  readonly maxDiskGiB: number;
  readonly peak: ComputeShape;
  readonly size: "512mb" | "1gb" | "2gb" | "4gb" | "8gb";
}

/** Everything the platform resolved for this session. */
export interface ResolvedConfig {
  readonly catalogRevision: string;
  readonly compute: ResolvedCompute;
  readonly lifecycle: SessionLifecyclePolicy;
  readonly model: string;
  readonly network: ResolvedNetwork;
  readonly packages: ReadonlyArray<PackageRequest>;
  readonly provider: ProviderId;
  readonly providerCredentialId: Id<"provider_credential">;
  readonly registered: SessionRegisteredSelection;
}

/** The resolved guest network policy. */
export interface ResolvedNetwork {
  readonly hands: HandsNetworkRequest;
}

/** A multi-turn conversation backed by at most one retained provider generation. Termination destroys compute and live files but preserves this metadata and sealed messages until deletion. */
export interface Session {
  readonly activeDeadline?: string;
  readonly activeMaxSpendCents?: string;
  readonly activeMessageId?: Id<"message">;
  readonly createdAt: string;
  readonly expiresAt: string;
  readonly id: Id<"session">;
  readonly idleSince?: string;
  readonly launchedAt: string;
  readonly metadata?: Readonly<Record<string, string | number | boolean | null>>;
  readonly resolvedConfig: ResolvedConfig;
  readonly revision: number;
  readonly status: SessionStatus;
  readonly suspendAt?: string;
  readonly suspendedAt?: string;
  readonly terminatedAt?: string;
  readonly terminationReason?: SessionTerminationReason;
  readonly updatedAt: string;
  readonly workspaceId: Id<"workspace">;
}

/** The result of cancelling the session's current work. The session is idle afterward and accepts another message. */
export interface SessionCancelResult {
  readonly changed: boolean;
  readonly sessionId: Id<"session">;
  readonly sessionRevision: number;
}

/** The only customer compute selector. */
export interface SessionComputeRequest {
  readonly size?: "512mb" | "1gb" | "2gb" | "4gb" | "8gb";
}

/** Create an eight-hour multi-turn session with one explicitly pinned BYOK provider credential. */
export interface SessionCreateRequest {
  readonly compute?: SessionComputeRequest;
  readonly metadata?: Readonly<Record<string, string | number | boolean | null>>;
  readonly model: string;
  readonly network?: SessionNetworkRequest;
  readonly packages?: ReadonlyArray<PackageRequest>;
  readonly provider: ProviderId;
  readonly providerCredentialId: Id<"provider_credential">;
  readonly registered?: SessionRegisteredSelection;
}

/** The immutable automatic lifecycle behavior applied to this session. */
export interface SessionLifecyclePolicy {
  readonly idleSuspendAfterSeconds: number;
  readonly maximumLifetimeSeconds: number;
  readonly resumeOnLiveFileAccess: boolean;
  readonly resumeOnMessage: boolean;
}

/** The collection projection of a session; `resolvedConfig` is omitted. */
export interface SessionListItem {
  readonly activeMessageId?: Id<"message">;
  readonly createdAt: string;
  readonly expiresAt: string;
  readonly id: Id<"session">;
  readonly model: string;
  readonly provider: ProviderId;
  readonly revision: number;
  readonly status: SessionStatus;
  readonly updatedAt: string;
  readonly workspaceId: Id<"workspace">;
}

/** One page of sessions. */
export interface SessionListPage {
  readonly items: ReadonlyArray<SessionListItem>;
  readonly nextCursor?: string;
}

/** Network policy for the session. */
export interface SessionNetworkRequest {
  readonly hands: HandsNetworkRequest;
}

/** Opaque workspace files mounted into the session. Conventional files such as `AGENTS.md` may carry guidance, skills, tool bundles, MCP configuration or custom instructions; the built-in model tools are `read_file`, `edit_file`, `write_file`, and Bash. */
export interface SessionRegisteredSelection {
  readonly files?: ReadonlyArray<string>;
}

/** The result of manually resuming the same retained generation to idle. */
export interface SessionResumeResult {
  readonly changed: boolean;
  readonly resumedAt: string;
  readonly sessionId: Id<"session">;
  readonly sessionRevision: number;
  readonly status: SessionStatus;
}

/** What a session is doing right now. */
export type SessionStatus = "idle" | "running" | "suspending" | "suspended" | "resuming" | "terminating" | "terminated" | "deleting";

/** The result of manually suspending an idle session's exact retained generation. Active work must be cancelled first. */
export interface SessionSuspendResult {
  readonly changed: boolean;
  readonly sessionId: Id<"session">;
  readonly sessionRevision: number;
  readonly suspendedAt: string;
}

/** A five-minute S3 GET grant for one immutable OTLP protobuf segment. */
export interface SessionTelemetryDownloadGrant {
  readonly expiresAt: string;
  readonly segment: SessionTelemetrySegment;
  readonly url: string;
}

/** One immutable official OTLP protobuf log segment generated by AEX after a committed session boundary. */
export interface SessionTelemetrySegment {
  readonly createdAt?: string;
  readonly id: string;
  readonly mediaType: string;
  readonly sequence: string;
  readonly sha256: string;
  readonly sizeBytes: string;
}

/** One bounded page of immutable AEX-generated session telemetry. */
export interface SessionTelemetrySegmentPage {
  readonly items: ReadonlyArray<SessionTelemetrySegment>;
  readonly nextCursor?: string;
}

/** The result of permanently destroying compute and live files while preserving session metadata and sealed messages. */
export interface SessionTerminateResult {
  readonly changed: boolean;
  readonly sessionId: Id<"session">;
  readonly sessionRevision: number;
  readonly terminatedAt: string;
}

/** Why a session permanently lost its compute and live files. */
export type SessionTerminationReason = "user" | "lifetime_expired" | "provider_credential_revoked" | "runtime_lost";

/** The minimal marker left after irreversible deletion. Compute and live files are terminated first; session, message, and Brain user-content payloads are removed. Independent registered workspace files and aggregate billing/audit facts remain. */
export interface SessionTombstone {
  readonly deletedAt: string;
  readonly id: Id<"session">;
  readonly operationId: Id<"operation">;
  readonly workspaceId: Id<"workspace">;
}

/** One immutable issued statement. The platform never rerenders history. */
export interface Statement {
  readonly artifactHash: string;
  readonly currency: Currency;
  readonly id: Id<"statement">;
  readonly issuedAt: string;
  readonly lines: ReadonlyArray<StatementLine>;
  readonly organizationId: Id<"organization">;
  readonly period: TimeRange;
  readonly totalCents: string;
}

/** One priced category line. Lines sum exactly to the statement total. */
export interface StatementLine {
  readonly category: UsageCategory;
  readonly totalCents: string;
}

/** The header of one immutable issued statement. */
export interface StatementSummary {
  readonly artifactHash: string;
  readonly currency: Currency;
  readonly id: Id<"statement">;
  readonly issuedAt: string;
  readonly organizationId: Id<"organization">;
  readonly period: TimeRange;
  readonly totalCents: string;
}

/** One page of statement headers, newest first. */
export interface StatementSummaryPage {
  readonly items: ReadonlyArray<StatementSummary>;
  readonly nextCursor?: string;
}

/** A half-open instant range, `gte` inclusive and `lt` exclusive. */
export interface TimeRange {
  readonly gte: string;
  readonly lt: string;
}

/** Create a hosted top-up checkout. */
export interface TopUpCheckoutRequest {
  readonly amountCents: string;
  readonly cancelUrl?: string;
  readonly successUrl?: string;
}

/** One staged multipart upload. Uploads are transport plumbing, not assets. */
export interface Upload {
  readonly contentType: string;
  readonly createdAt: string;
  readonly expiresAt: string;
  readonly id: Id<"upload">;
  readonly partCount: number;
  readonly partSizeBytes: string;
  readonly sha256: string;
  readonly sizeBytes: string;
  readonly state: UploadState;
}

/** Complete a staged upload. */
export interface UploadCompleteRequest {
  readonly parts: ReadonlyArray<UploadPart>;
}

/** Stage a large registered-resource value. */
export interface UploadCreateRequest {
  readonly contentType: string;
  readonly sha256: string;
  readonly sizeBytes: string;
}

/** One written part and the entity tag the store returned. */
export interface UploadPart {
  readonly etag: string;
  readonly partNumber: number;
}

/** One presigned PUT grant. The headers must be sent verbatim: they carry the part checksum and length the signature covers, and a PUT without them is rejected by the object store. */
export interface UploadPartGrant {
  readonly expiresAt: string;
  readonly headers: ReadonlyArray<HttpHeader>;
  readonly partNumber: number;
  readonly url: string;
}

/** The presigned grants for the requested parts. */
export interface UploadPartGrants {
  readonly grants: ReadonlyArray<UploadPartGrant>;
  readonly uploadId: Id<"upload">;
}

/** One part to presign. The part's own SHA-256 is required because S3 verifies it on the way up and the completion manifest checks it again; the server never sees the bytes, so it cannot compute it. */
export interface UploadPartRequest {
  readonly partNumber: number;
  readonly sha256: string;
  readonly sizeBytes: string;
}

/** Mint presigned PUT grants for the named parts. At most 1000 parts per call against the 10000-part ceiling, so a maximal upload needs at least ten calls. */
export interface UploadPartsRequest {
  readonly parts: ReadonlyArray<UploadPartRequest>;
}

/** Where a staged upload is in its lifecycle. */
export type UploadState = "staging" | "ready";

/** One resource aggregate, discriminated by category. */
export type UsageAggregate = (UsageStorageAggregate & { readonly category: "storage" }) | (UsageComputeAggregate & { readonly category: "compute" }) | (UsageMemoryAggregate & { readonly category: "memory" }) | (UsageDataTransferAggregate & { readonly category: "data_transfer" });

/** What a regional aggregate is attributed to. */
export interface UsageAttribution {
  readonly operationId?: Id<"operation">;
  readonly region: "us-east-1" | "us-east-2" | "us-west-2" | "ap-northeast-1" | "eu-west-1";
  readonly serviceTime: TimeRange;
  readonly sessionId?: Id<"session">;
  readonly source: string;
  readonly workspaceId: Id<"workspace">;
}

/** The three authorities that admit usage facts. There are three rather than
four because memory and compute are one contiguous fact sequence behind
one authority, so they share one frontier; publishing four frontiers with
two of them always identical would claim an independence that does not
exist.
 */
export type UsageAuthority = "storage" | "compute" | "transfer";

/** The time grain one usage query answers at. All bucketing is UTC and there
is no timezone parameter; a range must be aligned to whole buckets of the
requested grain and a misaligned range is refused rather than widened to
the enclosing buckets.
 */
export type UsageBucket = "hour" | "day" | "total";

/** The four priced categories. */
export type UsageCategory = "storage" | "compute" | "memory" | "data_transfer";

/** Millicpu-milliseconds of guest compute. */
export interface UsageComputeAggregate {
  readonly attribution: UsageAttribution;
  readonly millicpuMilliseconds: string;
  readonly settlement: UsageSettlement;
}

/** Measured outbound bytes. */
export interface UsageDataTransferAggregate {
  readonly attribution: UsageAttribution;
  readonly egressBytes: string;
  readonly settlement: UsageSettlement;
}

/** How far the pipeline has advanced for one workspace and authority. The
answer is exact at or below `completeThrough` and contains nothing above
`includesThrough`; between the two it is partial, and saying so is the
point. Both are monotone across repeated queries.
 */
export interface UsageFrontier {
  readonly acceptedSequence: string;
  readonly category: UsageAuthority;
  readonly completeThrough: string;
  readonly includesThrough: string;
  readonly projectedSequence: string;
  readonly publishedSequence: string;
  readonly region: "us-east-1" | "us-east-2" | "us-west-2" | "ap-northeast-1" | "eu-west-1";
  readonly serviceThrough?: string;
  readonly settledSequence: string;
  readonly stallReason?: string;
  readonly stalledAt?: string;
  readonly state: UsageFrontierState;
  readonly workspaceId: Id<"workspace">;
}

/** Whether a fold is advancing or parked. */
export type UsageFrontierState = "advancing" | "stalled";

/** The axes a usage query may group by. Session, run and operation are
deliberately absent: every stored aggregate row is keyed by a hash of a
seven-member dimension tuple that includes the session, so grouping by one
of them would read hundreds of thousands of rows for a single monthly
total. "How much did session X cost?" is not answerable by any route in
v1, and publishing an axis that is always refused would be a false
capability.
 */
export type UsageGrouping = "category" | "region" | "workspace";

/** Byte-milliseconds of guest memory. */
export interface UsageMemoryAggregate {
  readonly attribution: UsageAttribution;
  readonly byteMilliseconds: string;
  readonly settlement: UsageSettlement;
}

/** One page of usage quantities plus the frontiers that bound its completeness. Monetary statements remain a central finance read. */
export interface UsagePage {
  readonly frontiers: ReadonlyArray<UsageFrontier>;
  readonly items: ReadonlyArray<UsageAggregate>;
  readonly nextCursor?: string;
}

/** A bounded query over authoritative regional usage quantities. */
export interface UsageQuery {
  readonly bucket: UsageBucket;
  readonly categories?: ReadonlyArray<UsageCategory>;
  readonly cursor?: string;
  readonly groupBy?: ReadonlyArray<UsageGrouping>;
  readonly limit?: number;
  readonly timeRange: TimeRange;
}

/** Whether an item is covered by a committed settlement receipt as of
`completeThrough`. Not permanently terminal: a correction or a void
arrives as a new fact at a higher sequence and re-opens its bucket to
`provisional`.
 */
export type UsageSettlement = "settled" | "provisional";

/** Retained bytes over time. */
export interface UsageStorageAggregate {
  readonly attribution: UsageAttribution;
  readonly byteMinutes: string;
  readonly settlement: UsageSettlement;
}

/** A region-pinned execution and content boundary. */
export interface Workspace {
  readonly apiUrl: string;
  readonly createdAt: string;
  readonly deletionOperationId?: Id<"operation">;
  readonly id: Id<"workspace">;
  readonly name: string;
  readonly operationalState: WorkspaceOperationalState;
  readonly organizationId: Id<"organization">;
  readonly region: "us-east-1" | "us-east-2" | "us-west-2" | "ap-northeast-1" | "eu-west-1";
  readonly slug: string;
  readonly status: WorkspaceStatus;
}

/** Which retained session generation answered a live workspace call. */
export interface WorkspaceAccess {
  readonly generationId: Id<"generation">;
  readonly resumed: boolean;
}

/** Create a region-pinned workspace. Region is required and immutable. */
export interface WorkspaceCreateRequest {
  readonly name: string;
  readonly organizationId: Id<"organization">;
  readonly region: "us-east-1" | "us-east-2" | "us-west-2" | "ap-northeast-1" | "eu-west-1";
}

/** Admit the global workspace-deletion operation. */
export interface WorkspaceDeleteRequest {
  readonly confirmation: Id<"workspace">;
}

/** The workspace view of the account operational state it inherits. */
export interface WorkspaceOperationalState {
  readonly inheritedFrom: OperationalStateSource;
  readonly organizationId: Id<"organization">;
  readonly state: AccountOperationalState;
}

/** One page of workspaces. */
export interface WorkspacePage {
  readonly items: ReadonlyArray<Workspace>;
  readonly nextCursor?: string;
}

/** Whether a workspace admits work. */
export type WorkspaceStatus = "active" | "deleting";

/** What remains of a deleted workspace. */
export interface WorkspaceTombstone {
  readonly deletedAt: string;
  readonly operationId: Id<"operation">;
  readonly organizationId: Id<"organization">;
  readonly workspaceId: Id<"workspace">;
}
